import XCTest

final class TapTests: XCTestCase {
    func testOpenTeamStandupRoomInfo() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()

        let room = app.staticTexts["Team Standup"].firstMatch
        XCTAssertTrue(room.waitForExistence(timeout: 30), "room row not found")
        room.tap()

        let headerText = app.navigationBars.staticTexts["Team Standup"].firstMatch
        let headerButton = app.navigationBars.buttons["Team Standup"].firstMatch
        var tapped = false
        if headerText.waitForExistence(timeout: 30) {
            headerText.tap()
            tapped = true
        } else if headerButton.waitForExistence(timeout: 5) {
            headerButton.tap()
            tapped = true
        }
        XCTAssertTrue(tapped, "room header not found")
        Thread.sleep(forTimeInterval: 4)
        print("HIERARCHY_START")
        print(app.debugDescription)
        print("HIERARCHY_END")
    }
}

import XCTest

final class TapTests: XCTestCase {
    func testDismissDialog() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()

        let gotIt = app.buttons["Got it"].firstMatch
        if gotIt.waitForExistence(timeout: 10) {
            gotIt.tap()
        }
        Thread.sleep(forTimeInterval: 2)
    }
}

