import XCTest

final class TapTests: XCTestCase {
    func testOpenRoomInfo() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()

        let headerText = app.navigationBars.staticTexts["Team Standup"].firstMatch
        XCTAssertTrue(headerText.waitForExistence(timeout: 15), "header not found")

        func onDetails() -> Bool {
            return app.staticTexts["Favourite"].firstMatch.exists
                || app.switches["Favourite"].firstMatch.exists
                || app.staticTexts["People"].firstMatch.exists
        }

        headerText.tap()
        if !onDetails() {
            let titlePoint = app.coordinate(withNormalizedOffset: CGVector(dx: 0.63, dy: 0.089))
            titlePoint.tap()
        }
        Thread.sleep(forTimeInterval: 3)
        print("ON_DETAILS=\(onDetails())")
        print("HIERARCHY_START")
        print(app.debugDescription)
        print("HIERARCHY_END")
    }
}

