import XCTest

final class TapTests: XCTestCase {
    func testOpenRoomInfo() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()

        func onDetails() -> Bool {
            return !app.otherElements["RoomVCView"].exists
        }

        let nameField = app.textFields["DisplayNameTextField"].firstMatch
        XCTAssertTrue(nameField.waitForExistence(timeout: 15), "title view not found")

        nameField.tap()
        if !onDetails() {
            app.coordinate(withNormalizedOffset: CGVector(dx: 0.18, dy: 0.089)).tap()
        }
        if !onDetails() {
            app.coordinate(withNormalizedOffset: CGVector(dx: 0.40, dy: 0.089)).tap()
        }
        Thread.sleep(forTimeInterval: 3)
        print("ON_DETAILS=\(onDetails())")
        print("HIERARCHY_START")
        print(app.debugDescription)
        print("HIERARCHY_END")
    }
}
